import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { cn } from '@gntik-ai/ui';
import { CalendarHeader } from '../shared/CalendarHeader';
import { addDays, addMonths, dayKey, formatFullDate, formatMonth, formatTime, monthGrid, sameDay, sameMonth, startOfDay, startOfMonth, startOfWeek } from '../shared/dates';
import { defaultEventKinds, groupByDay, kindOf, TONE, type EventKind, type ScheduleEvent } from '../shared/events';
import { sampleEvents, sampleToday } from '../shared/fixtures';

export interface MonthCalendarProps {
  events?: ScheduleEvent[];
  /** The app's "today" (the block never reads the clock). */
  today?: Date;
  /** Month shown first (uncontrolled). Defaults to the month of `today`. */
  defaultMonth?: Date;
  onMonthChange?: (month: Date) => void;
  /** Initially selected day (uncontrolled). */
  defaultSelected?: Date;
  /** Called when a day is activated (click, Enter or Space). */
  onSelectDate?: (date: Date, events: ScheduleEvent[]) => void;
  /** Event kinds (label, icon, tone) by `event.kind`. */
  kinds?: Record<string, EventKind>;
  /** Event lines per day before "+N more". */
  maxEventsPerDay?: number;
  /** Caller actions in the header (e.g. a "Schedule" button). */
  actions?: ReactNode;
  className?: string;
}

const WEEKDAYS = [
  ['Mon', 'Monday'],
  ['Tue', 'Tuesday'],
  ['Wed', 'Wednesday'],
  ['Thu', 'Thursday'],
  ['Fri', 'Friday'],
  ['Sat', 'Saturday'],
  ['Sun', 'Sunday'],
] as const;

const plural = (n: number) => (n === 1 ? '1 event' : `${n} events`);

/**
 * Month view of scheduled work: a Monday-first grid with up to N events per day.
 * Keyboard: arrows move by day/week, Home/End to the week edges, PageUp/PageDown by month,
 * Enter/Space selects.
 */
export function MonthCalendar({
  events = sampleEvents,
  today = sampleToday,
  defaultMonth,
  onMonthChange,
  defaultSelected,
  onSelectDate,
  kinds = defaultEventKinds,
  maxEventsPerDay = 2,
  actions,
  className,
}: MonthCalendarProps) {
  const titleId = useId();
  const [selected, setSelected] = useState<Date>(() => startOfDay(defaultSelected ?? today));
  const [focused, setFocused] = useState<Date>(() => startOfDay(defaultSelected ?? defaultMonth ?? today));
  const [month, setMonth] = useState<Date>(() => startOfMonth(defaultMonth ?? defaultSelected ?? today));
  const gridRef = useRef<HTMLDivElement>(null);
  const moveFocus = useRef(false);
  const byDay = useMemo(() => groupByDay(events), [events]);
  const weeks = monthGrid(month);
  // The roving tab stop stays inside the visible month.
  const tabStop = sameMonth(focused, month) ? focused : sameMonth(selected, month) ? selected : month;

  useEffect(() => {
    if (!moveFocus.current) return;
    moveFocus.current = false;
    gridRef.current?.querySelector<HTMLElement>(`[data-date="${dayKey(focused)}"]`)?.focus();
  }, [focused]);

  const showMonth = (next: Date) => {
    const first = startOfMonth(next);
    setMonth(first);
    onMonthChange?.(first);
  };

  const go = (date: Date) => {
    setFocused(date);
    if (!sameMonth(date, month)) showMonth(date);
    moveFocus.current = true;
  };

  const select = (date: Date) => {
    setSelected(date);
    setFocused(date);
    onSelectDate?.(date, byDay.get(dayKey(date)) ?? []);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, date: Date) => {
    const weekStart = startOfWeek(date);
    const map: Record<string, () => Date> = {
      ArrowLeft: () => addDays(date, -1),
      ArrowRight: () => addDays(date, 1),
      ArrowUp: () => addDays(date, -7),
      ArrowDown: () => addDays(date, 7),
      Home: () => weekStart,
      End: () => addDays(weekStart, 6),
      PageUp: () => new Date(date.getFullYear(), date.getMonth() - 1, Math.min(date.getDate(), 28)),
      PageDown: () => new Date(date.getFullYear(), date.getMonth() + 1, Math.min(date.getDate(), 28)),
    };
    const next = map[event.key];
    if (!next) return;
    event.preventDefault();
    go(next());
  };

  return (
    <div className={cn('overflow-hidden rounded-xl border border-border bg-card', className)}>
      <CalendarHeader
        titleId={titleId}
        title={formatMonth(month)}
        prevLabel="Previous month"
        nextLabel="Next month"
        onPrev={() => showMonth(addMonths(month, -1))}
        onNext={() => showMonth(addMonths(month, 1))}
        onToday={() => {
          showMonth(today);
          setFocused(startOfDay(today));
        }}
        actions={actions}
      />
      <div ref={gridRef} role="grid" aria-labelledby={titleId}>
        <div role="row" className="grid grid-cols-7 border-b border-border bg-secondary/30">
          {WEEKDAYS.map(([short, long]) => (
            <div
              key={short}
              role="columnheader"
              aria-label={long}
              className="py-2 text-center text-[11px] font-medium tracking-wide text-muted-foreground uppercase"
            >
              {short}
            </div>
          ))}
        </div>
        {weeks.map((week) => (
          <div key={dayKey(week[0] ?? month)} role="row" className="grid grid-cols-7">
            {week.map((date) => {
              const key = dayKey(date);
              const list = byDay.get(key) ?? [];
              const inMonth = sameMonth(date, month);
              const isToday = sameDay(date, today);
              const isSelected = sameDay(date, selected);
              const extra = list.length - maxEventsPerDay;
              return (
                <div key={key} role="gridcell" aria-selected={isSelected} className="min-w-0 border-e border-b border-border/70 [&:nth-child(7)]:border-e-0">
                  <button
                    type="button"
                    data-date={key}
                    tabIndex={sameDay(date, tabStop) ? 0 : -1}
                    aria-label={`${formatFullDate(date)}${list.length ? `, ${plural(list.length)}` : ''}`}
                    aria-current={isToday ? 'date' : undefined}
                    onClick={() => select(date)}
                    onKeyDown={(e) => onKeyDown(e, date)}
                    className={cn(
                      'flex h-full min-h-14 w-full flex-col items-stretch p-1.5 text-start transition-colors motion-reduce:transition-none sm:min-h-[92px] sm:p-2',
                      'hover:bg-accent/30 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus-ring',
                      inMonth ? 'bg-card' : 'bg-secondary/20',
                    )}
                  >
                    <span className="flex items-center justify-between">
                      <span
                        className={cn(
                          'inline-flex size-6 items-center justify-center rounded-full text-[12px] font-medium tabular-nums',
                          isToday
                            ? 'bg-primary font-semibold text-primary-foreground'
                            : isSelected
                              ? 'bg-secondary text-foreground ring-1 ring-border'
                              : inMonth
                                ? 'text-foreground'
                                : 'text-muted-foreground',
                        )}
                      >
                        {date.getDate()}
                      </span>
                      {isSelected && !isToday && <span aria-hidden className="size-1.5 rounded-full bg-primary" />}
                    </span>
                    {list.length > 0 && (
                      <span aria-hidden className="mt-1 flex gap-0.5 sm:hidden">
                        {list.slice(0, 3).map((e) => (
                          <span key={e.id} className={cn('size-1.5 rounded-full', TONE[kindOf(e, kinds).tone].dot)} />
                        ))}
                      </span>
                    )}
                    <span aria-hidden className="mt-1.5 hidden space-y-1 sm:block">
                      {list.slice(0, maxEventsPerDay).map((e) => (
                        <span key={e.id} className="flex min-w-0 items-center gap-1.5">
                          <span className={cn('size-1.5 shrink-0 rounded-full', TONE[kindOf(e, kinds).tone].dot)} />
                          <span className="truncate text-[11px] text-foreground/80">{e.title}</span>
                          <span className="ms-auto hidden shrink-0 font-mono text-[10px] text-muted-foreground xl:block">{formatTime(e.start)}</span>
                        </span>
                      ))}
                      {extra > 0 && <span className="block ps-3 text-[10.5px] text-muted-foreground">+ {extra} more</span>}
                    </span>
                  </button>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ReactNode } from 'react';
import { Button, IconButton } from '@gntik-ai/ui';
import { ChevronLeft, ChevronRight } from '@gntik-ai/icons';

export interface CalendarHeaderProps {
  titleId: string;
  title: string;
  subtitle?: string;
  prevLabel: string;
  nextLabel: string;
  onPrev: () => void;
  onNext: () => void;
  onToday: () => void;
  actions?: ReactNode;
}

/** Title + previous / today / next navigation + caller actions. */
export function CalendarHeader({ titleId, title, subtitle, prevLabel, nextLabel, onPrev, onNext, onToday, actions }: CalendarHeaderProps) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-4 py-3 sm:px-5">
      <div className="min-w-0">
        <h3 id={titleId} aria-live="polite" className="truncate text-[15px] font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {subtitle && <p className="mt-0.5 truncate font-mono text-[11px] text-muted-foreground">{subtitle}</p>}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <div className="flex items-center gap-1">
          <IconButton icon={ChevronLeft} label={prevLabel} variant="secondary" size="sm" onClick={onPrev} />
          <Button variant="secondary" size="sm" onClick={onToday}>
            Today
          </Button>
          <IconButton icon={ChevronRight} label={nextLabel} variant="secondary" size="sm" onClick={onNext} />
        </div>
        {actions}
      </div>
    </div>
  );
}

/** Native-Date helpers for the scheduling blocks. Weeks start on Monday. */

const pad = (n: number) => String(n).padStart(2, '0');

/** Local calendar key "YYYY-MM-DD". */
export function dayKey(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

export function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

export function addDays(d: Date, n: number): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
}

export function addMonths(d: Date, n: number): Date {
  return new Date(d.getFullYear(), d.getMonth() + n, 1);
}

export function startOfMonth(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), 1);
}

export function sameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

export function sameMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

/** Monday of the week containing `d`. */
export function startOfWeek(d: Date): Date {
  return addDays(startOfDay(d), -((d.getDay() + 6) % 7));
}

export function weekDays(d: Date): Date[] {
  const mon = startOfWeek(d);
  return Array.from({ length: 7 }, (_, i) => addDays(mon, i));
}

/** Six Monday-first weeks covering the month of `d`. */
export function monthGrid(d: Date): Date[][] {
  const start = startOfWeek(startOfMonth(d));
  return Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, i) => addDays(start, w * 7 + i)));
}

/** Decimal hour of the day: 10:30 → 10.5. */
export function hourOf(d: Date): number {
  return d.getHours() + d.getMinutes() / 60;
}

const fmt = (opts: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat('en-US', opts);
const timeFmt = fmt({ hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fullFmt = fmt({ weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
const dayFmt = fmt({ weekday: 'long', month: 'long', day: 'numeric' });
const monthFmt = fmt({ month: 'long', year: 'numeric' });
const shortFmt = fmt({ month: 'short', day: 'numeric' });
const weekdayFmt = fmt({ weekday: 'short' });

/** "09:30". */
export const formatTime = (d: Date) => timeFmt.format(d);
/** "09:30–10:00". */
export const formatRange = (start: Date, end: Date) => `${formatTime(start)}–${formatTime(end)}`;
/** "Wednesday, April 15, 2026". */
export const formatFullDate = (d: Date) => fullFmt.format(d);
/** "Wednesday, April 15". */
export const formatDay = (d: Date) => dayFmt.format(d);
/** "April 2026". */
export const formatMonth = (d: Date) => monthFmt.format(d);
/** "Apr 15". */
export const formatShort = (d: Date) => shortFmt.format(d);
/** "Wed". */
export const formatWeekday = (d: Date) => weekdayFmt.format(d);

/** "Apr 13 – 19, 2026" (or across months / years). */
export function formatWeekRange(days: readonly Date[]): string {
  const first = days[0];
  const last = days[days.length - 1];
  if (!first || !last) return '';
  if (sameMonth(first, last)) return `${formatShort(first)} – ${last.getDate()}, ${last.getFullYear()}`;
  if (first.getFullYear() === last.getFullYear()) return `${formatShort(first)} – ${formatShort(last)}, ${last.getFullYear()}`;
  return `${formatShort(first)}, ${first.getFullYear()} – ${formatShort(last)}, ${last.getFullYear()}`;
}

import { CalendarCheck, Cog, Database, RefreshCw, ShieldCheck, Upload, type LucideIcon } from '@gntik-ai/icons';
import type { BadgeTone } from '@gntik-ai/ui';
import { dayKey } from './dates';

/** A scheduled item on a calendar. */
export interface ScheduleEvent {
  id: string;
  title: string;
  start: Date;
  end: Date;
  /** Key into the `kinds` map (job, deploy, review, backup, maintenance…). */
  kind?: string;
  /** Region, room or target, shown after the time. */
  location?: string;
}

export type EventTone = 'primary' | 'violet' | 'cyan' | 'amber' | 'neutral';

export interface EventKind {
  label: string;
  icon: LucideIcon;
  tone: EventTone;
}

/** Default kinds: brand green for jobs, categorical accents for the rest (never severity). */
export const defaultEventKinds: Record<string, EventKind> = {
  job: { label: 'Job', icon: RefreshCw, tone: 'primary' },
  deploy: { label: 'Deploy', icon: Upload, tone: 'violet' },
  review: { label: 'Review', icon: ShieldCheck, tone: 'cyan' },
  backup: { label: 'Backup', icon: Database, tone: 'amber' },
  maintenance: { label: 'Maintenance', icon: Cog, tone: 'neutral' },
};

const FALLBACK: EventKind = { label: 'Event', icon: CalendarCheck, tone: 'primary' };

export function kindOf(event: ScheduleEvent, kinds: Record<string, EventKind>): EventKind {
  return (event.kind ? kinds[event.kind] : undefined) ?? FALLBACK;
}

/** Token classes per tone. Text stays foreground on category tints (no contrast alias for them). */
export const TONE: Record<EventTone, { dot: string; soft: string; bar: string; icon: string; badge: BadgeTone }> = {
  primary: { dot: 'bg-primary', soft: 'bg-primary/12', bar: 'border-primary', icon: 'text-primary-text', badge: 'primary' },
  violet: { dot: 'bg-category-violet', soft: 'bg-category-violet/14', bar: 'border-category-violet', icon: 'text-foreground', badge: 'violet' },
  cyan: { dot: 'bg-category-cyan', soft: 'bg-category-cyan/14', bar: 'border-category-cyan', icon: 'text-foreground', badge: 'cyan' },
  amber: { dot: 'bg-category-amber', soft: 'bg-category-amber/16', bar: 'border-category-amber', icon: 'text-foreground', badge: 'amber' },
  neutral: { dot: 'bg-muted-foreground', soft: 'bg-secondary', bar: 'border-muted-foreground', icon: 'text-muted-foreground', badge: 'neutral' },
};

/** Events grouped by local day key, each day sorted by start. */
export function groupByDay(events: readonly ScheduleEvent[]): Map<string, ScheduleEvent[]> {
  const map = new Map<string, ScheduleEvent[]>();
  for (const e of events) {
    const key = dayKey(e.start);
    const list = map.get(key);
    if (list) list.push(e);
    else map.set(key, [e]);
  }
  for (const list of map.values()) list.sort((a, b) => a.start.getTime() - b.start.getTime());
  return map;
}
